-- PT116-S2-Q3. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT116-S2-Q3$batch03$ AND q.stimulus=$batch03$Cognitive psychologist: In a recent survey, citizens of Country F were asked to state which one of the following two scenarios they would prefer: (1) Country F is the world economic leader, with a gross national product (GNP) of $100 billion, and Country G is second, with a GNP of $90 billion; or (2) Country G is the economic leader, with a GNP of $120 billion, and Country F is second, with a GNP of $110 billion. Despite the fact that, under scenario 2, Country F would have a higher GNP than under scenario 1, the majority of respondents stated that they preferred scenario 1.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, would most help to explain the survey results described by the cognitive psychologist?$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT116-S2-Q3$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT116-S2-Q3$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Under scenario 2, Country F would have a higher GNP ($110 billion vs $100 billion).$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Most citizens of F prefer scenario 1?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$What does scenario 1 offer that scenario 2 does not? In scenario 1, F is the world leader, ahead of G. In scenario 2, G is ahead. If people care more about being ahead of G than about their own total, scenario 1 wins.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a preference for ranking above G over a higher absolute GNP.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT116-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$A belief about growth rates does not decide between the two fixed scenarios.$batch03$), ($batch03$B$batch03$, $batch03$Wanting a GNP above $120 billion would favor scenario 2, which comes closer.$batch03$), ($batch03$C$batch03$, $batch03$If GNP does not affect personal welfare, people might be indifferent between the scenarios. It does not explain a preference for the lower GNP.$batch03$), ($batch03$D$batch03$, $batch03$If GNP is a poor measure, people again have little reason to care either way. That gives no reason to prefer scenario 1.$batch03$), ($batch03$E$batch03$, $batch03$Citizens want F to be more economically powerful than G. Only scenario 1 delivers that, so they choose it even though F's GNP is lower.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT116-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
